  addBooks("eng6", [{"title":"Character & Plot Development","subtitle":"Understanding character types, motivation, and story structure","sections":[{"title":"Character Types & Traits","questions":[{"type":"regular","q":"What is a character who opposes the main character called?","answer":"antagonist","solution":"The antagonist is the character or force that creates conflict against the protagonist."},{"type":"regular","q":"True or False: A static character changes significantly throughout the story.","answer":"False","solution":"A static character remains the same; a dynamic character changes over time."},{"type":"word","q":"Which word means the reason a character acts or behaves a certain way?","answer":"motivation","solution":"Motivation explains why a character does something in the story."}]},{"title":"Plot Structure & Conflict","questions":[{"type":"regular","q":"What is the turning point in a story where the main character's fortune changes called?","answer":"climax","solution":"The climax is the moment of greatest tension and the turning point of the plot."},{"type":"regular","q":"Name the part of a story that introduces characters and setting before the main action begins.","answer":"exposition","solution":"Exposition provides background information at the beginning of a story."},{"type":"word","q":"What word describes the struggle between opposing forces in a story?","answer":"conflict","solution":"Conflict is the central problem or struggle that drives the plot forward."}]},{"title":"Character Motivation & Development","questions":[{"type":"regular","q":"What technique does an author use to show character development through a character's own thoughts?","answer":"internal monologue or stream of consciousness","solution":"Internal monologue reveals a character's thoughts and feelings directly to the reader."},{"type":"regular","q":"True or False: A character's motivation must always be positive or good.","answer":"False","solution":"Characters can be motivated by negative desires like revenge, greed, or jealousy."},{"type":"word","q":"What is the process by which a character grows and changes through experiences called?","answer":"character arc","solution":"A character arc shows the transformation a character undergoes from beginning to end."}]}]},{"title":"Persuasive Writing & Rhetoric","subtitle":"Crafting arguments and using rhetorical techniques to convince readers","sections":[{"title":"Argument Structure & Evidence","questions":[{"type":"regular","q":"What is the main point or position that a writer wants to convince readers to believe?","answer":"claim or thesis","solution":"A claim is the central argument the writer wants readers to accept."},{"type":"regular","q":"Name three types of evidence that can support a persuasive argument.","answer":"facts, statistics, expert opinions, examples, or personal anecdotes","solution":"Strong evidence includes factual data, expert testimony, and relevant examples."},{"type":"word","q":"What is a statement that contradicts the writer's claim called?","answer":"counterargument","solution":"A counterargument presents the opposing view that the writer then refutes."}]},{"title":"Rhetorical Techniques & Appeals","questions":[{"type":"regular","q":"Which appeal to emotion uses a sad or moving story to persuade readers?","answer":"pathos","solution":"Pathos appeals to the reader's emotions to create a persuasive connection."},{"type":"regular","q":"True or False: Using facts and logical reasoning to persuade is called ethos.","answer":"False","solution":"Logos uses logic and facts; ethos appeals to credibility and trustworthiness."},{"type":"word","q":"What technique repeats a word or phrase for emphasis and persuasive effect?","answer":"repetition","solution":"Repetition reinforces key ideas and makes arguments more memorable."}]},{"title":"Evaluating & Responding to Persuasion","questions":[{"type":"regular","q":"What is a logical error in reasoning that weakens an argument called?","answer":"logical fallacy","solution":"A logical fallacy is a flaw in reasoning that makes an argument invalid."},{"type":"regular","q":"Name a common logical fallacy where someone attacks the person instead of their argument.","answer":"ad hominem","solution":"Ad hominem attacks the character of the opponent rather than addressing the argument."},{"type":"word","q":"What is the credibility and trustworthiness of a speaker or writer called?","answer":"ethos","solution":"Ethos is the appeal to the writer's credibility and authority on a topic."}]}]},{"title":"Narrative & Point of View","subtitle":"Analyzing how narrators shape stories and reader perspective","sections":[{"title":"Point of View & Narrative Perspective","questions":[{"type":"regular","q":"What point of view uses 'I' or 'we' and tells the story from a character's perspective?","answer":"first person","solution":"First-person narration is told from the perspective of a character in the story."},{"type":"regular","q":"In which point of view can the narrator see into the thoughts of all characters?","answer":"third-person omniscient","solution":"An omniscient narrator knows the thoughts and feelings of all characters."},{"type":"word","q":"What is the perspective that uses 'he,' 'she,' or 'they' but only knows one character's thoughts?","answer":"third-person limited","solution":"Third-person limited narration is told from outside but restricted to one character's perspective."}]},{"title":"Narrator Reliability & Voice","questions":[{"type":"regular","q":"What is a narrator who lies or misrepresents events called?","answer":"unreliable narrator","solution":"An unreliable narrator cannot be fully trusted to tell the truth about events."},{"type":"regular","q":"True or False: A first-person narrator always knows everything that happens in the story.","answer":"False","solution":"A first-person narrator only knows what their character experiences or learns."},{"type":"word","q":"What is the unique style and personality of a narrator's speech called?","answer":"narrative voice","solution":"Narrative voice includes the narrator's tone, word choice, and distinctive way of telling the story."}]},{"title":"Effect of Point of View on Meaning","questions":[{"type":"regular","q":"How might a story change if told from the antagonist's point of view instead of the protagonist's?","answer":"The reader would understand the antagonist's motivations and might sympathize with them differently.","solution":"Changing point of view shifts the reader's understanding and sympathy toward different characters."},{"type":"regular","q":"What does an omniscient narrator allow readers to do that a first-person narrator does not?","answer":"See events from multiple perspectives or know information the main character doesn't know","solution":"Omniscient narration provides broader knowledge than a single character's limited perspective."},{"type":"word","q":"What literary technique involves the narrator knowing more than the characters?","answer":"dramatic irony","solution":"Dramatic irony occurs when the reader knows something the character does not."}]}]},{"title":"Comparing Texts & Media","subtitle":"Analyzing similarities and differences across genres and formats","sections":[{"title":"Text Comparison & Analysis","questions":[{"type":"regular","q":"What is the process of examining how two texts are similar called?","answer":"comparison","solution":"Comparison identifies shared elements, themes, or techniques between texts."},{"type":"regular","q":"Name two texts that could be compared: a novel and a ___.","answer":"short story, play, poem, film, or article","solution":"Any two texts with similar themes or subjects can be compared for similarities and differences."},{"type":"word","q":"What is the examination of how two texts differ in approach or style called?","answer":"contrast","solution":"Contrast identifies the differences between texts in theme, tone, structure, or technique."}]},{"title":"Analyzing Different Media Formats","questions":[{"type":"regular","q":"What is a visual representation or adaptation of a written story called?","answer":"film adaptation or visual media","solution":"A film adaptation translates a written story into visual and audio format."},{"type":"regular","q":"True or False: A movie and a book version of the same story will always have identical plots.","answer":"False","solution":"Adaptations often change plots, characters, or details due to different medium constraints."},{"type":"word","q":"What elements of a story might be shown through images and sound in a film but told through words in a book?","answer":"setting, mood, atmosphere, or character appearance","solution":"Visual and audio media show these elements directly, while text must describe them."}]},{"title":"Evaluating Source Credibility & Bias","questions":[{"type":"regular","q":"What is a prejudice or preference that influences how information is presented called?","answer":"bias","solution":"Bias is a slant or preference that affects how a text presents information."},{"type":"regular","q":"Name three questions you should ask to determine if a source is credible.","answer":"Who wrote it? What is their expertise? Is it from a reliable publisher? Are sources cited? Is it recent?","solution":"Evaluating author credentials, publication source, and evidence helps determine credibility."},{"type":"word","q":"What is the purpose or goal an author has in writing a text called?","answer":"author's purpose","solution":"Author's purpose explains why the writer created the text (to inform, persuade, entertain, etc.)."}]}]},{"title":"Grammar & Sentence Variety","subtitle":"Mastering sentence types and grammatical structures for clear writing","sections":[{"title":"Sentence Types & Structures","questions":[{"type":"regular","q":"What is a sentence with one independent clause and no dependent clauses called?","answer":"simple sentence","solution":"A simple sentence contains one independent clause with a subject and verb."},{"type":"regular","q":"Name the sentence type that joins two independent clauses with a coordinating conjunction.","answer":"compound sentence","solution":"A compound sentence combines two independent clauses with conjunctions like 'and,' 'but,' or 'or.'"},{"type":"word","q":"What is a sentence that contains an independent clause and one or more dependent clauses called?","answer":"complex sentence","solution":"A complex sentence has an independent clause plus dependent clauses that add information."}]},{"title":"Verb Tense & Agreement","questions":[{"type":"regular","q":"True or False: A verb must always agree in number with its subject.","answer":"True","solution":"Subjects and verbs must agree in number; singular subjects take singular verbs."},{"type":"regular","q":"Correct this sentence: 'The team are playing well.' What should 'are' be changed to?","answer":"is","solution":"'Team' is a collective noun treated as singular, so it takes 'is' instead of 'are.'"},{"type":"word","q":"What is the form of a verb that shows when an action happens (past, present, future)?","answer":"tense","solution":"Verb tense indicates the time of an action or state of being."}]},{"title":"Sentence Variety & Combining","questions":[{"type":"regular","q":"Why is it important to vary sentence length and structure in writing?","answer":"It creates rhythm, maintains reader interest, and prevents monotony.","solution":"Sentence variety makes writing more engaging and easier to read."},{"type":"regular","q":"Combine these two sentences using a subordinating conjunction: 'I studied hard. I passed the test.'","answer":"Because I studied hard, I passed the test. / I passed the test because I studied hard.","solution":"A subordinating conjunction like 'because' combines sentences and shows the relationship between ideas."},{"type":"word","q":"What is a word that joins a dependent clause to an independent clause called?","answer":"subordinating conjunction","solution":"Subordinating conjunctions like 'because,' 'although,' and 'when' connect dependent clauses to independent ones."}]}]}]);
  addBooks("eng7", [{"title":"Persuasive Writing & Rhetoric","subtitle":"Master argument, evidence, and persuasive techniques","sections":[{"title":"Identifying Persuasive Appeals","questions":[{"type":"regular","q":"Which appeal uses emotion to persuade an audience?","answer":"Pathos","solution":"Pathos is the rhetorical appeal that connects to emotions and feelings."},{"type":"regular","q":"True or False: An ethos appeal relies on the credibility and trustworthiness of the speaker.","answer":"True","solution":"Ethos establishes the speaker's authority and character to build trust."},{"type":"word","q":"What is the term for a logical appeal that uses facts, statistics, and reasoning?","answer":"Logos","solution":"Logos appeals to logic and reason with evidence and data."}]},{"title":"Building Strong Arguments","questions":[{"type":"regular","q":"What is a claim in an argument?","answer":"The main point or position the writer wants to prove","solution":"A claim is the central argument that the rest of the piece supports."},{"type":"regular","q":"True or False: A counterargument weakens your persuasive essay.","answer":"False","solution":"Addressing counterarguments actually strengthens your argument by showing you understand opposing views."},{"type":"word","q":"What do you call information used to support a claim?","answer":"Evidence","solution":"Evidence includes facts, examples, quotes, and data that back up your claim."}]},{"title":"Persuasive Techniques & Devices","questions":[{"type":"regular","q":"What technique repeats a word or phrase for emphasis and effect?","answer":"Repetition","solution":"Repetition reinforces ideas and makes messages more memorable."},{"type":"regular","q":"True or False: A rhetorical question expects a literal answer from the audience.","answer":"False","solution":"Rhetorical questions are asked for effect and don't require an actual answer."},{"type":"word","q":"What is the name for an extreme exaggeration used for persuasive effect?","answer":"Hyperbole","solution":"Hyperbole overstates something dramatically to emphasize a point."}]}]},{"title":"Greek & Latin Roots","subtitle":"Build vocabulary through word origins and morphology","sections":[{"title":"Common Greek Roots","questions":[{"type":"regular","q":"What does the Greek root 'bio' mean?","answer":"Life","solution":"Bio appears in words like biography and biology, all relating to life."},{"type":"regular","q":"True or False: The Greek root 'graph' means to write.","answer":"True","solution":"Graph comes from Greek and appears in words like autograph and paragraph."},{"type":"word","q":"What Greek root meaning 'sound' appears in the word 'telephone'?","answer":"Phon","solution":"Phon (phone) is the Greek root for sound; telephone means 'distant sound.'"}]},{"title":"Common Latin Roots","questions":[{"type":"regular","q":"What does the Latin root 'port' mean?","answer":"Carry or transport","solution":"Port appears in words like portable, transport, and export."},{"type":"regular","q":"True or False: The Latin root 'aud' relates to hearing.","answer":"True","solution":"Aud means to hear and appears in audience, audition, and audio."},{"type":"word","q":"What Latin root meaning 'to see' appears in the word 'visible'?","answer":"Vis","solution":"Vis is the Latin root for see; visible means 'able to be seen.'"}]},{"title":"Prefixes & Suffixes","questions":[{"type":"regular","q":"What does the prefix 'un-' mean?","answer":"Not","solution":"Un- is a negative prefix that reverses or negates the meaning of a word."},{"type":"regular","q":"True or False: The suffix '-tion' typically creates nouns.","answer":"True","solution":"The suffix -tion converts verbs into nouns (e.g., create → creation)."},{"type":"word","q":"What prefix meaning 'before' appears in the word 'preview'?","answer":"Pre-","solution":"Pre- means before and appears in preview, predict, and prepare."}]}]},{"title":"Character Development & Motivation","subtitle":"Analyze how characters change and why they act","sections":[{"title":"Types of Characters","questions":[{"type":"regular","q":"What is a round character?","answer":"A character who is complex, develops, and changes throughout the story","solution":"Round characters have depth, multiple traits, and undergo transformation."},{"type":"regular","q":"True or False: A flat character typically has one main trait or purpose.","answer":"True","solution":"Flat characters are simple and don't change significantly; they serve a specific role."},{"type":"word","q":"What do you call a character who opposes the protagonist?","answer":"Antagonist","solution":"The antagonist is the opposing force or character in conflict with the protagonist."}]},{"title":"Character Motivation & Conflict","questions":[{"type":"regular","q":"What is character motivation?","answer":"The reasons why a character acts or makes decisions","solution":"Motivation explains what drives a character's actions and choices."},{"type":"regular","q":"True or False: Internal conflict occurs between a character and another person.","answer":"False","solution":"Internal conflict is a struggle within a character's mind; external conflict is with others or the environment."},{"type":"word","q":"What is the term for a character's gradual change over time?","answer":"Character arc","solution":"A character arc traces how a character evolves from beginning to end."}]},{"title":"Analyzing Character Relationships","questions":[{"type":"regular","q":"What does it mean when a character is a foil?","answer":"The character contrasts with another to highlight their differences","solution":"A foil character emphasizes traits in another character through comparison."},{"type":"regular","q":"True or False: Character dialogue can reveal personality and motivation.","answer":"True","solution":"What characters say and how they say it reveals their traits, values, and intentions."},{"type":"word","q":"What literary technique shows a character's thoughts and feelings directly?","answer":"Internal monologue or stream of consciousness","solution":"This technique allows readers to access a character's mind and understand their perspective."}]}]},{"title":"Narrative Point of View & Voice","subtitle":"Understand how perspective shapes storytelling","sections":[{"title":"Points of View","questions":[{"type":"regular","q":"What point of view uses 'I' and 'we' to tell the story?","answer":"First person","solution":"First-person narration is told from the perspective of a character in the story."},{"type":"regular","q":"True or False: In third-person omniscient, the narrator knows all characters' thoughts and feelings.","answer":"True","solution":"An omniscient narrator has complete knowledge of all characters' inner lives."},{"type":"word","q":"What point of view uses 'he,' 'she,' and 'they' but only shows one character's perspective?","answer":"Third-person limited","solution":"Third-person limited follows one character's thoughts while using third-person pronouns."}]},{"title":"Narrator Reliability & Bias","questions":[{"type":"regular","q":"What is an unreliable narrator?","answer":"A narrator whose account cannot be fully trusted due to bias, deception, or limited knowledge","solution":"Unreliable narrators may lie, misunderstand, or have skewed perspectives."},{"type":"regular","q":"True or False: A first-person narrator always tells the complete truth.","answer":"False","solution":"First-person narrators can be biased, mistaken, or deliberately deceptive."},{"type":"word","q":"What is the narrator's distinctive style of speaking and thinking called?","answer":"Voice","solution":"Narrative voice includes word choice, tone, and perspective unique to the narrator."}]},{"title":"Effects of Point of View","questions":[{"type":"regular","q":"How does first-person narration affect reader connection to the story?","answer":"It creates intimacy and immediacy by allowing readers to experience events through a character's eyes","solution":"First-person perspective draws readers into the narrator's personal experience."},{"type":"regular","q":"True or False: Third-person omniscient creates more suspense than first-person narration.","answer":"False","solution":"First-person narration typically creates more suspense because readers only know what the narrator knows."},{"type":"word","q":"What is the advantage of using second-person point of view ('you')?","answer":"It directly addresses the reader and creates immediacy or involvement","solution":"Second person is rare but can make readers feel personally involved in the narrative."}]}]},{"title":"Tone, Mood & Author's Purpose","subtitle":"Identify emotional atmosphere and authorial intent","sections":[{"title":"Understanding Tone","questions":[{"type":"regular","q":"What is tone in writing?","answer":"The author's attitude toward the subject and audience","solution":"Tone reflects the writer's feelings and perspective, conveyed through word choice and style."},{"type":"regular","q":"True or False: Tone and mood are the same thing.","answer":"False","solution":"Tone is the author's attitude; mood is the emotional atmosphere the reader experiences."},{"type":"word","q":"What tone is created when an author uses sarcasm and irony?","answer":"Sarcastic or ironic tone","solution":"Sarcasm and irony create a tone that says one thing but means another."}]},{"title":"Analyzing Mood & Atmosphere","questions":[{"type":"regular","q":"What creates mood in a text?","answer":"Word choice, imagery, setting, and tone work together to create an emotional atmosphere","solution":"Mood is the feeling or emotional quality a reader experiences while reading."},{"type":"regular","q":"True or False: A dark, stormy setting typically creates a cheerful mood.","answer":"False","solution":"Dark, stormy settings usually create tense, ominous, or melancholic moods."},{"type":"word","q":"What literary device uses descriptive language to create mood?","answer":"Imagery","solution":"Imagery appeals to the senses to create vivid mental pictures and emotional responses."}]},{"title":"Author's Purpose & Intent","questions":[{"type":"regular","q":"What are the main purposes an author might have for writing?","answer":"To inform, entertain, persuade, or express ideas/emotions","solution":"Authors write with specific goals that shape their choices in content and style."},{"type":"regular","q":"True or False: An author's purpose is always explicitly stated in the text.","answer":"False","solution":"Readers must infer purpose from the author's choices, tone, and content."},{"type":"word","q":"What technique does an author use to reveal their purpose indirectly?","answer":"Implication or inference","solution":"Authors show purpose through subtle choices that readers must interpret and analyze."}]}]}]);
  addBooks("eng8", [{"title":"Persuasive Writing & Rhetoric","subtitle":"Master argument techniques, appeals, and persuasive strategies","sections":[{"title":"Rhetorical Appeals & Techniques","questions":[{"type":"regular","q":"What is the rhetorical appeal that uses logic and evidence to convince an audience?","answer":"Ethos or logos (logos is the most direct answer)","solution":"Logos relies on facts, statistics, and logical reasoning to build a persuasive argument."},{"type":"regular","q":"True or False: A bandwagon appeal tries to convince you to do something because 'everyone else is doing it.'","answer":"True","solution":"Bandwagon is a fallacy that exploits the desire to fit in with the crowd."},{"type":"word","q":"What is the term for a statement presented as fact without proof?","answer":"Assertion or claim","solution":"An assertion is a statement made confidently but without evidence; persuasive writing must support assertions with reasoning."}]},{"title":"Identifying & Analyzing Arguments","questions":[{"type":"regular","q":"What is the main point or position that a writer wants you to accept called?","answer":"Thesis or claim","solution":"The thesis is the central argument that the entire persuasive piece supports."},{"type":"regular","q":"Name one logical fallacy where someone attacks the person making an argument instead of the argument itself.","answer":"Ad hominem","solution":"Ad hominem attacks the character of the speaker rather than addressing the actual argument."},{"type":"word","q":"What do you call evidence that directly supports a claim?","answer":"Supporting evidence or proof","solution":"Supporting evidence includes facts, examples, expert testimony, or statistics that back up a claim."}]},{"title":"Counterarguments & Refutation","questions":[{"type":"regular","q":"What is an opposing viewpoint to your main argument called?","answer":"Counterargument or opposing argument","solution":"Acknowledging counterarguments makes your persuasive writing stronger and more credible."},{"type":"regular","q":"True or False: Strong persuasive writing should ignore opposing viewpoints entirely.","answer":"False","solution":"Effective persuasion addresses counterarguments and explains why your position is stronger."},{"type":"word","q":"What is the process of disproving or weakening an opposing argument called?","answer":"Refutation","solution":"Refutation involves presenting evidence or reasoning that contradicts or undermines a counterargument."}]}]},{"title":"Character Development & Motivation","subtitle":"Analyze how characters change, develop, and drive narrative action","sections":[{"title":"Character Traits & Archetypes","questions":[{"type":"regular","q":"What is a quality or characteristic that describes a person called?","answer":"Trait or character trait","solution":"Character traits are the qualities—both physical and personality-based—that define who a character is."},{"type":"regular","q":"True or False: A static character changes significantly throughout a story.","answer":"False","solution":"A static character remains largely the same; a dynamic character changes over the course of the story."},{"type":"word","q":"What is a universal character type that appears across many stories and cultures?","answer":"Archetype","solution":"Archetypes like the hero, mentor, or trickster are recurring character patterns in literature."}]},{"title":"Character Motivation & Conflict","questions":[{"type":"regular","q":"What is the reason or desire that drives a character to act called?","answer":"Motivation","solution":"Motivation explains why a character does what they do and makes their actions believable."},{"type":"regular","q":"Name the type of conflict where a character struggles against another character.","answer":"External conflict or character vs. character","solution":"External conflict occurs between a character and an outside force, such as another person."},{"type":"word","q":"What is an internal struggle within a character's mind or emotions called?","answer":"Internal conflict or character vs. self","solution":"Internal conflict shows a character's doubts, fears, or moral dilemmas."}]},{"title":"Character Relationships & Growth","questions":[{"type":"regular","q":"What is the main character of a story called?","answer":"Protagonist","solution":"The protagonist is the central character whose journey or conflict drives the plot."},{"type":"regular","q":"True or False: A foil character helps highlight the protagonist's traits by being similar to them.","answer":"False","solution":"A foil character is different from the protagonist and emphasizes their qualities by contrast."},{"type":"word","q":"What is the process of a character becoming wiser or more mature through experience called?","answer":"Character development or growth","solution":"Character development shows how experiences and conflicts transform a character over time."}]}]},{"title":"Theme & Symbolism in Literature","subtitle":"Identify and interpret themes, symbols, and deeper meanings in texts","sections":[{"title":"Understanding Theme","questions":[{"type":"regular","q":"What is the central idea or message about life that a story conveys?","answer":"Theme","solution":"Theme is the underlying meaning or lesson that a literary work communicates to readers."},{"type":"regular","q":"True or False: A story can have only one theme.","answer":"False","solution":"Most stories explore multiple themes, and different readers may interpret themes differently."},{"type":"word","q":"What is the difference between a theme and a plot summary?","answer":"Theme is the deeper meaning; plot is what happens","solution":"Plot describes events; theme is the universal truth or message those events reveal."}]},{"title":"Symbols & Symbolism","questions":[{"type":"regular","q":"What is an object, character, or action that represents something beyond its literal meaning?","answer":"Symbol","solution":"A symbol carries deeper meaning and often represents abstract ideas like hope, death, or freedom."},{"type":"regular","q":"In literature, what does a white dove typically symbolize?","answer":"Peace or purity","solution":"White doves are traditional symbols of peace and innocence in Western literature."},{"type":"word","q":"What is the use of symbols to represent ideas or qualities in a work called?","answer":"Symbolism","solution":"Symbolism is the literary technique of using symbols to add layers of meaning to a text."}]},{"title":"Interpreting Deeper Meanings","questions":[{"type":"regular","q":"What is a story's surface-level meaning called?","answer":"Literal meaning or denotation","solution":"Literal meaning is what actually happens in the story without interpretation."},{"type":"regular","q":"True or False: An author's use of imagery always has symbolic meaning.","answer":"False","solution":"While imagery can be symbolic, it often serves primarily to create vivid descriptions."},{"type":"word","q":"What is the implied or suggested meaning of a word or image beyond its definition?","answer":"Connotation","solution":"Connotation includes the emotional and cultural associations a word carries beyond its literal definition."}]}]},{"title":"Poetry Analysis & Interpretation","subtitle":"Examine poetic devices, structure, and meaning in verse","sections":[{"title":"Poetic Devices & Sound","questions":[{"type":"regular","q":"What is the repetition of beginning consonant sounds in nearby words called?","answer":"Alliteration","solution":"Alliteration creates rhythm and emphasis through repeated initial consonant sounds."},{"type":"regular","q":"True or False: Onomatopoeia is a word that imitates the sound it represents.","answer":"True","solution":"Words like 'buzz,' 'hiss,' and 'splash' are onomatopoeia that echo their meanings."},{"type":"word","q":"What is a comparison between two unlike things using 'like' or 'as' called?","answer":"Simile","solution":"A simile directly compares two things using 'like' or 'as' to create vivid imagery."}]},{"title":"Poetic Structure & Form","questions":[{"type":"regular","q":"What is a group of lines in a poem called?","answer":"Stanza","solution":"Stanzas are the verse equivalent of paragraphs in prose."},{"type":"regular","q":"What is the pattern of stressed and unstressed syllables in a line of poetry called?","answer":"Meter or rhythm","solution":"Meter creates the musical quality of poetry through its regular pattern of beats."},{"type":"word","q":"What is a 14-line poem with a specific rhyme scheme, often about love?","answer":"Sonnet","solution":"A sonnet is a traditional poetic form with strict structure and often explores themes of love or beauty."}]},{"title":"Figurative Language & Tone","questions":[{"type":"regular","q":"What is a direct comparison between two unlike things without using 'like' or 'as'?","answer":"Metaphor","solution":"A metaphor states that one thing IS another to create a powerful comparison."},{"type":"regular","q":"True or False: The tone of a poem is always the same as the poet's actual feelings.","answer":"False","solution":"A poet may adopt a tone different from their own feelings to create irony or explore ideas."},{"type":"word","q":"What is the attitude or emotional quality a poem conveys toward its subject?","answer":"Tone","solution":"Tone reflects the poet's attitude and shapes how readers interpret the poem's meaning."}]}]},{"title":"Informational Text & Media Literacy","subtitle":"Evaluate credibility, bias, and purpose in nonfiction and digital sources","sections":[{"title":"Author's Purpose & Bias","questions":[{"type":"regular","q":"What is the author's main reason for writing a text called?","answer":"Author's purpose or intent","solution":"Common purposes include to inform, persuade, entertain, or explain."},{"type":"regular","q":"True or False: All informational texts are completely objective and free from bias.","answer":"False","solution":"Even factual writing can reflect an author's perspective, word choice, and what they choose to include or omit."},{"type":"word","q":"What is a personal preference or prejudice that influences how information is presented?","answer":"Bias","solution":"Bias can be intentional or unintentional and affects which facts are emphasized or ignored."}]},{"title":"Evaluating Source Credibility","questions":[{"type":"regular","q":"Name one factor you should check to determine if a source is credible.","answer":"Author expertise, publication date, publisher reputation, or citations (any one is acceptable)","solution":"Credible sources come from knowledgeable authors, reputable publishers, and current information."},{"type":"regular","q":"True or False: Information found on the internet is always reliable.","answer":"False","solution":"Online sources vary widely in quality; you must evaluate each source individually for credibility."},{"type":"word","q":"What is the practice of checking facts against multiple reliable sources called?","answer":"Fact-checking or verification","solution":"Cross-referencing information across credible sources helps confirm accuracy and identify misinformation."}]},{"title":"Media Analysis & Persuasion","questions":[{"type":"regular","q":"What is a visual or multimedia element used to persuade an audience called?","answer":"Media or visual rhetoric","solution":"Images, videos, and graphics are powerful persuasive tools that work alongside text."},{"type":"regular","q":"True or False: Photographs in advertisements always show exactly what a product looks like in real life.","answer":"False","solution":"Photos can be edited, filtered, or taken from flattering angles to manipulate how products appear."},{"type":"word","q":"What is misleading or false information spread deliberately to deceive people called?","answer":"Misinformation or disinformation","solution":"Misinformation can spread rapidly on social media and requires critical evaluation to identify."}]}]}]);
  addBooks("eng9", [{"title":"Character Development & Analysis","subtitle":"Examining how characters evolve through conflict and choice","sections":[{"title":"Character Archetypes & Motivation","questions":[{"type":"regular","q":"What is the primary difference between a static character and a dynamic character?","answer":"A static character does not change significantly, while a dynamic character undergoes meaningful change throughout the story.","solution":"Static characters remain the same, while dynamic characters transform based on events and experiences."},{"type":"regular","q":"Name one character motivation that would drive a protagonist to commit a morally questionable act.","answer":"Answers may include: protecting a loved one, survival, revenge, ambition, or seeking justice.","solution":"Complex motivations reveal character depth and create internal conflict."},{"type":"word","q":"What term describes a character who opposes the protagonist and drives the central conflict?","answer":"antagonist","solution":"The antagonist is the opposing force that creates tension and challenges for the protagonist."}]},{"title":"Characterization Techniques","questions":[{"type":"regular","q":"What does it mean when a character is revealed through direct characterization?","answer":"The author explicitly tells the reader about the character's traits, thoughts, or feelings.","solution":"Direct characterization provides straightforward information about who a character is."},{"type":"regular","q":"How can a character's dialogue reveal their personality or background?","answer":"Through word choice, accent, grammar, tone, and what they choose to discuss or avoid.","solution":"Speech patterns and content expose character traits without author explanation."},{"type":"word","q":"What is the literary term for a character's consistent pattern of behavior and thinking?","answer":"characterization","solution":"Characterization is how an author develops and reveals a character's personality."}]},{"title":"Internal & External Conflict","questions":[{"type":"regular","q":"What is an example of internal conflict a character might experience?","answer":"Answers may include: doubt about a decision, guilt, fear, desire vs. duty, or moral dilemma.","solution":"Internal conflict occurs within a character's mind or emotions."},{"type":"regular","q":"How does external conflict differ from internal conflict?","answer":"External conflict involves a character struggling against an outside force (person, nature, society), while internal conflict is a struggle within the character themselves.","solution":"External conflicts are visible struggles; internal conflicts are psychological or emotional."},{"type":"word","q":"What term describes a struggle between a character and another character, nature, or society?","answer":"external conflict","solution":"External conflict is any struggle between a character and an outside force."}]}]},{"title":"Vocabulary & Word Study","subtitle":"Building academic vocabulary through context and word relationships","sections":[{"title":"Context Clues & Inference","questions":[{"type":"regular","q":"Read: 'The old mansion was dilapidated, with broken windows and crumbling walls.' What does 'dilapidated' mean based on context?","answer":"In poor condition; falling apart or decayed.","solution":"The descriptive phrases 'broken windows' and 'crumbling walls' provide context clues."},{"type":"regular","q":"What are three types of context clues that can help you understand an unfamiliar word?","answer":"Definition/explanation, synonym, antonym, example, or comparison clues.","solution":"Context clues surround unfamiliar words and reveal their meaning."},{"type":"word","q":"What is the term for a word that means the opposite of another word?","answer":"antonym","solution":"Antonyms are words with opposite meanings and can serve as context clues."}]},{"title":"Prefixes, Suffixes & Word Roots","questions":[{"type":"regular","q":"What does the prefix 'un-' mean, and give an example of a word using it.","answer":"It means 'not' or 'opposite of.' Examples: unhappy, undo, unclear.","solution":"The prefix 'un-' negates or reverses the meaning of the root word."},{"type":"regular","q":"If 'bio' means life and 'graphy' means writing, what does 'biography' mean?","answer":"A written account of someone's life.","solution":"Breaking words into roots and affixes reveals meaning through word parts."},{"type":"word","q":"What is the term for a word part added to the end of a root word to change its meaning?","answer":"suffix","solution":"Suffixes modify root words and often change their part of speech or meaning."}]},{"title":"Academic & Domain-Specific Vocabulary","questions":[{"type":"regular","q":"In literary analysis, what does 'theme' mean?","answer":"The central idea or underlying message of a text.","solution":"Theme is the main idea that the author explores throughout the work."},{"type":"regular","q":"What is the difference between 'tone' and 'mood' in literature?","answer":"Tone is the author's attitude toward the subject; mood is the emotional atmosphere created for the reader.","solution":"Tone reflects the author's voice; mood reflects the reader's emotional response."},{"type":"word","q":"What term describes the sequence of events in a story?","answer":"plot","solution":"Plot is the organized sequence of events that make up the narrative."}]}]},{"title":"Figurative Language & Literary Devices","subtitle":"Understanding metaphor, simile, symbolism, and other literary techniques","sections":[{"title":"Simile, Metaphor & Personification","questions":[{"type":"regular","q":"Identify whether this is a simile or metaphor: 'Her smile was as bright as the sun.'","answer":"Simile.","solution":"The use of 'as...as' indicates a simile; metaphors do not use 'like' or 'as.'"},{"type":"regular","q":"What does personification do in literature?","answer":"It gives human qualities or characteristics to non-human things or animals.","solution":"Personification makes inanimate objects or animals seem alive and relatable."},{"type":"word","q":"What is a direct comparison between two unlike things without using 'like' or 'as' called?","answer":"metaphor","solution":"A metaphor states that one thing IS another, creating a direct comparison."}]},{"title":"Symbolism & Imagery","questions":[{"type":"regular","q":"What is a symbol in literature?","answer":"A person, object, place, or action that represents something beyond its literal meaning.","solution":"Symbols carry deeper meaning and add layers of interpretation to a text."},{"type":"regular","q":"How does imagery contribute to a reader's understanding of a story?","answer":"Imagery uses sensory details to create vivid mental pictures and evoke emotions.","solution":"Descriptive sensory language helps readers visualize and emotionally connect to the text."},{"type":"word","q":"What term describes the use of sensory details to create a mental picture?","answer":"imagery","solution":"Imagery appeals to the senses and helps readers visualize scenes and emotions."}]},{"title":"Irony, Hyperbole & Allusion","questions":[{"type":"regular","q":"What is verbal irony?","answer":"When someone says the opposite of what they mean, often for effect or humor.","solution":"Verbal irony occurs when words express something contrary to what is actually meant."},{"type":"regular","q":"Give an example of hyperbole and explain its purpose.","answer":"Example: 'I've told you a million times.' Purpose: to exaggerate for emphasis or humor.","solution":"Hyperbole uses extreme exaggeration to create emphasis or comic effect."},{"type":"word","q":"What is an indirect reference to another work, person, or event called?","answer":"allusion","solution":"An allusion briefly references something outside the text to add meaning or context."}]}]},{"title":"Essay Structure & Composition","subtitle":"Crafting organized, coherent essays with strong thesis and support","sections":[{"title":"Thesis Statements & Topic Sentences","questions":[{"type":"regular","q":"What is the purpose of a thesis statement?","answer":"To present the main argument or central idea of an essay in a clear, specific way.","solution":"A thesis statement guides the entire essay and tells readers what to expect."},{"type":"regular","q":"Evaluate this thesis: 'Shakespeare wrote many plays.' Why is it weak?","answer":"It is too general and does not make a specific argument or claim.","solution":"Strong thesis statements are specific, arguable, and clearly state the essay's main point."},{"type":"word","q":"What is a sentence at the beginning of a paragraph that introduces its main idea?","answer":"topic sentence","solution":"Topic sentences organize paragraphs and connect to the thesis."}]},{"title":"Evidence & Supporting Details","questions":[{"type":"regular","q":"What are three types of evidence you can use to support a claim in an essay?","answer":"Quotes from texts, statistics, expert opinions, examples, or personal observations.","solution":"Varied evidence types strengthen arguments and demonstrate thorough research."},{"type":"regular","q":"Why is it important to explain how evidence supports your claim?","answer":"Because the connection between evidence and claim must be clear to readers.","solution":"Analysis explains the significance of evidence and prevents readers from drawing wrong conclusions."},{"type":"word","q":"What is the process of explaining how evidence proves your point called?","answer":"analysis","solution":"Analysis connects evidence to claims and develops ideas thoroughly."}]},{"title":"Organization & Coherence","questions":[{"type":"regular","q":"What is the typical structure of a five-paragraph essay?","answer":"Introduction with thesis, three body paragraphs with supporting evidence, and a conclusion.","solution":"This structure provides clear organization and allows for development of multiple ideas."},{"type":"regular","q":"How do transition words improve essay coherence?","answer":"They connect ideas between sentences and paragraphs, showing relationships and flow.","solution":"Transitions like 'furthermore,' 'however,' and 'in conclusion' guide readers through arguments."},{"type":"word","q":"What term describes the logical flow and connection of ideas in writing?","answer":"coherence","solution":"Coherence ensures that ideas are organized and connected in a way readers can follow."}]}]},{"title":"Reading Comprehension & Critical Analysis","subtitle":"Developing strategies to understand and evaluate texts deeply","sections":[{"title":"Identifying Main Ideas & Supporting Details","questions":[{"type":"regular","q":"What is the difference between a main idea and a supporting detail?","answer":"The main idea is the central point of a text or paragraph; supporting details provide evidence or examples that explain it.","solution":"Main ideas are broader; supporting details are specific facts that reinforce them."},{"type":"regular","q":"How can you identify the main idea of a paragraph?","answer":"Look for the topic sentence, consider what most sentences discuss, or ask what the paragraph is mainly about.","solution":"The main idea is usually stated directly or can be inferred from the overall content."},{"type":"word","q":"What is a statement that sums up the most important point of a text?","answer":"main idea","solution":"The main idea is the central concept that the text develops and supports."}]},{"title":"Inference & Drawing Conclusions","questions":[{"type":"regular","q":"What is an inference in reading?","answer":"A logical conclusion based on evidence in the text combined with prior knowledge.","solution":"Inferences require readers to 'read between the lines' and use textual clues."},{"type":"regular","q":"Read: 'Marcus stared at the letter for five minutes without opening it. His hands trembled.' What can you infer about Marcus's emotional state?","answer":"He is anxious, nervous, or afraid of what the letter contains.","solution":"The details about staring and trembling suggest emotional distress or fear."},{"type":"word","q":"What is the process of using text clues and background knowledge to figure out something not directly stated?","answer":"inference","solution":"Inference allows readers to understand implied meanings and deeper layers of text."}]},{"title":"Evaluating Author's Purpose & Perspective","questions":[{"type":"regular","q":"What are four common purposes an author might have for writing?","answer":"To inform, entertain, persuade, or express ideas/emotions.","solution":"Understanding author's purpose helps readers interpret tone, style, and message."},{"type":"regular","q":"How can an author's perspective or bias affect how a story is told?","answer":"It influences which details are included, what is emphasized, and how characters or events are portrayed.","solution":"Perspective shapes narrative voice and determines what readers learn and believe."},{"type":"word","q":"What is the author's reason for writing a text?","answer":"author's purpose","solution":"Author's purpose guides the content, tone, and structure of a piece of writing."}]}]}]);
  addBooks("eng10", [{"title":"Poetry Analysis & Interpretation","subtitle":"Analyzing poetic devices, form, and meaning in verse","sections":[{"title":"Poetic Devices & Sound","questions":[{"type":"regular","q":"In the line 'The fair breeze blew, the white foam flew,' what device is used to create rhythm and musicality?","answer":"Alliteration","solution":"The repetition of the 'f' sound in 'fair,' 'breeze,' 'blew,' 'foam,' and 'flew' creates alliteration."},{"type":"regular","q":"What is the term for a line of poetry that does not end with punctuation and continues into the next line?","answer":"Enjambment","solution":"Enjambment occurs when a grammatical phrase or clause continues beyond the line break without terminal punctuation."},{"type":"word","q":"The repetition of vowel sounds within words in a line of poetry is called ___.","answer":"Assonance","solution":"Assonance is the repetition of vowel sounds (like 'o' in 'home' and 'stone') within nearby words."}]},{"title":"Poetic Form & Structure","questions":[{"type":"regular","q":"A 14-line poem with a specific rhyme scheme, traditionally used to explore a single theme or argument, is called a ___.","answer":"Sonnet","solution":"A sonnet is a 14-line poem, often in iambic pentameter, with forms like Shakespearean (ABAB CDCD EFEF GG) or Petrarchan."},{"type":"regular","q":"True or False: Free verse poetry must follow a strict meter and rhyme scheme.","answer":"False","solution":"Free verse deliberately abandons regular meter and rhyme to allow greater flexibility in expression."},{"type":"word","q":"A stanza is a grouped set of ___ in a poem, similar to a paragraph in prose.","answer":"Lines","solution":"Stanzas are divisions of lines in poetry that organize thought and create visual structure on the page."}]},{"title":"Imagery, Tone & Theme","questions":[{"type":"regular","q":"What is the overall emotional quality or attitude conveyed by a poem called?","answer":"Tone","solution":"Tone refers to the speaker's attitude toward the subject, conveyed through word choice, rhythm, and imagery."},{"type":"regular","q":"In Emily Dickinson's 'Hope is the thing with feathers,' what literary device is used to describe hope?","answer":"Metaphor","solution":"Hope is directly compared to a bird without using 'like' or 'as,' making it a metaphor rather than a simile."},{"type":"word","q":"Descriptive language that appeals to the five senses to create vivid pictures is called ___.","answer":"Imagery","solution":"Imagery uses sensory details (sight, sound, smell, taste, touch) to help readers visualize and experience the poem."}]}]},{"title":"Argumentative Writing & Evidence","subtitle":"Constructing claims, using evidence, and refuting counterarguments","sections":[{"title":"Claims & Thesis Development","questions":[{"type":"regular","q":"What is the difference between a claim and an opinion?","answer":"A claim is supported by evidence; an opinion is a personal belief without required support.","solution":"Claims are arguable statements backed by reasoning and evidence, while opinions are subjective preferences."},{"type":"regular","q":"True or False: A thesis statement in an argumentative essay should be vague to allow for multiple interpretations.","answer":"False","solution":"A thesis should be clear, specific, and arguable to guide the reader and establish the essay's direction."},{"type":"word","q":"A statement that presents the main argument of an essay, typically in the introduction, is called a ___.","answer":"Thesis","solution":"The thesis statement is the central claim that the entire essay supports through evidence and reasoning."}]},{"title":"Evidence & Counterarguments","questions":[{"type":"regular","q":"What are the three main types of evidence used to support an argument?","answer":"Logical, emotional, and ethical (or: facts/statistics, expert testimony, and examples)","solution":"Strong arguments use logos (logic), pathos (emotion), and ethos (credibility) to persuade the audience."},{"type":"regular","q":"When a writer acknowledges and responds to an opposing viewpoint, this is called a ___.","answer":"Counterargument","solution":"Addressing counterarguments strengthens an essay by showing the writer has considered alternative perspectives."},{"type":"word","q":"A logical fallacy in which a conclusion is drawn from insufficient or irrelevant evidence is called ___.","answer":"Hasty generalization","solution":"Hasty generalization occurs when a broad conclusion is made from limited examples or evidence."}]},{"title":"Logical Fallacies & Credibility","questions":[{"type":"regular","q":"What is an ad hominem fallacy?","answer":"Attacking the person making the argument rather than addressing the argument itself.","solution":"Ad hominem attacks the character or background of the speaker instead of refuting their actual claims."},{"type":"regular","q":"True or False: Using emotional language alone is sufficient to make a strong argument.","answer":"False","solution":"While emotional appeal can be effective, strong arguments require logical evidence and credible sources too."},{"type":"word","q":"The credibility and trustworthiness of a writer or speaker is called their ___.","answer":"Ethos","solution":"Ethos is one of Aristotle's three appeals and refers to the author's authority and reliability on the topic."}]}]},{"title":"Character Development & Motivation","subtitle":"Analyzing how characters change and what drives their actions","sections":[{"title":"Character Types & Archetypes","questions":[{"type":"regular","q":"What is the difference between a protagonist and an antagonist?","answer":"The protagonist is the main character; the antagonist opposes or conflicts with the protagonist.","solution":"The protagonist drives the plot forward while the antagonist creates obstacles or conflict."},{"type":"regular","q":"A character who remains essentially unchanged throughout a story is called a ___.","answer":"Static character","solution":"Static characters do not undergo significant development or change in their beliefs or personality."},{"type":"word","q":"A character who undergoes significant internal change or growth is called a ___ character.","answer":"Dynamic","solution":"Dynamic characters evolve and transform through their experiences and interactions in the story."}]},{"title":"Motivation & Internal Conflict","questions":[{"type":"regular","q":"What is character motivation?","answer":"The reasons, desires, or needs that drive a character's actions and decisions.","solution":"Understanding motivation helps readers comprehend why characters behave as they do in the story."},{"type":"regular","q":"True or False: A character's motivation must always be clearly stated by the narrator.","answer":"False","solution":"Readers often infer motivation from a character's actions, dialogue, and thoughts rather than explicit statements."},{"type":"word","q":"A struggle between two opposing desires or values within a single character is called ___ conflict.","answer":"Internal","solution":"Internal conflict occurs within a character's mind as they wrestle with competing emotions or goals."}]},{"title":"Character Relationships & Development","questions":[{"type":"regular","q":"How can a character's interactions with other characters reveal their personality and values?","answer":"Through dialogue, actions, and reactions that show how they treat others and respond to conflict.","solution":"Character relationships expose personality traits and motivations that might not be apparent in isolation."},{"type":"regular","q":"What is a foil character?","answer":"A character whose qualities contrast with another character, highlighting their differences.","solution":"Foil characters serve to emphasize and clarify the traits of the main character through comparison."},{"type":"word","q":"The process by which a character gradually changes and grows throughout a narrative is called ___.","answer":"Character arc","solution":"A character arc traces the transformation of a character from beginning to end of the story."}]}]},{"title":"Narrative Structure & Plot Development","subtitle":"Understanding story structure, pacing, and narrative techniques","sections":[{"title":"Plot Elements & Story Structure","questions":[{"type":"regular","q":"What are the five main elements of plot structure?","answer":"Exposition, rising action, climax, falling action, and resolution.","solution":"These elements organize a narrative from introduction through conflict to conclusion."},{"type":"regular","q":"The turning point or moment of greatest tension in a story is called the ___.","answer":"Climax","solution":"The climax is where the main conflict reaches its peak and the outcome becomes clear."},{"type":"word","q":"The background information provided at the beginning of a story is called the ___.","answer":"Exposition","solution":"Exposition introduces characters, setting, and background necessary for understanding the story."}]},{"title":"Narrative Point of View & Perspective","questions":[{"type":"regular","q":"What is the difference between first-person and third-person narration?","answer":"First-person uses 'I' and is told by a character; third-person uses 'he/she/they' and is told by an outside narrator.","solution":"First-person provides intimate access to one character's thoughts; third-person offers broader perspective."},{"type":"regular","q":"True or False: An unreliable narrator always tells the truth but interprets events incorrectly.","answer":"False","solution":"An unreliable narrator may lie, misremember, or be biased, leading readers to question their account."},{"type":"word","q":"A narrator who knows all characters' thoughts and feelings is using ___ point of view.","answer":"Omniscient","solution":"Omniscient narrators have complete knowledge of all characters' inner lives and motivations."}]},{"title":"Pacing, Flashback & Foreshadowing","questions":[{"type":"regular","q":"What is foreshadowing?","answer":"Hints or clues that suggest future events in the story.","solution":"Foreshadowing builds suspense and prepares readers for developments that occur later."},{"type":"regular","q":"A scene that interrupts the main narrative to show events from the past is called a ___.","answer":"Flashback","solution":"Flashbacks provide background information or context that helps explain current events or character motivations."},{"type":"word","q":"The speed at which events unfold in a narrative is called ___.","answer":"Pacing","solution":"Pacing controls how quickly or slowly the story moves, affecting reader engagement and tension."}]}]},{"title":"Tone, Mood & Style in Literature","subtitle":"Examining how authors create atmosphere and voice through language choices","sections":[{"title":"Tone & Author's Attitude","questions":[{"type":"regular","q":"What is the difference between tone and mood?","answer":"Tone is the author's attitude; mood is the emotional atmosphere created for the reader.","solution":"Tone reflects the writer's perspective while mood describes the feeling the reader experiences."},{"type":"regular","q":"How can word choice reveal an author's tone?","answer":"Through diction—the selection of formal, informal, positive, negative, or neutral words.","solution":"Word choice conveys attitude; for example, 'slender' versus 'scrawny' reveals different perspectives."},{"type":"word","q":"A tone that uses humor to criticize or mock something is called ___.","answer":"Ironic","solution":"Ironic tone says one thing but means another, often to highlight absurdity or hypocrisy."}]},{"title":"Mood & Atmosphere","questions":[{"type":"regular","q":"What literary elements contribute to creating mood in a text?","answer":"Imagery, setting, word choice, rhythm, and figurative language.","solution":"These elements work together to establish the emotional atmosphere and reader response."},{"type":"regular","q":"True or False: Mood and tone are always the same in a piece of literature.","answer":"False","solution":"An author can maintain a sarcastic tone while creating a tense or frightening mood for readers."},{"type":"word","q":"The overall feeling or emotional quality of a text is called its ___.","answer":"Mood","solution":"Mood encompasses the emotional atmosphere that envelops the reader throughout the narrative."}]},{"title":"Style & Literary Voice","questions":[{"type":"regular","q":"What is an author's literary style?","answer":"The distinctive way an author uses language, including sentence structure, word choice, and techniques.","solution":"Style is the unique combination of writing choices that makes an author's work recognizable."},{"type":"regular","q":"How do sentence length and structure affect the pace and tone of a passage?","answer":"Short sentences create urgency and tension; long sentences create complexity and reflection.","solution":"Sentence variety controls rhythm and helps establish the author's intended emotional effect."},{"type":"word","q":"The distinctive personality and perspective of a narrator or speaker is called their ___.","answer":"Voice","solution":"Voice is the unique way a character or narrator expresses themselves through language and perspective."}]}]}]);
  addBooks("eng11", [{"title":"British Literature: Romanticism to Modernism","subtitle":"Explore transformative British literary movements and canonical texts.","sections":[{"title":"Romantic Era & Poets","questions":[{"type":"regular","q":"Which Romantic poet wrote 'Ozymandias' and explored themes of power and decay?","answer":"Percy Bysshe Shelley","solution":"Shelley's sonnet 'Ozymandias' is a cornerstone Romantic work about the transience of human power."},{"type":"regular","q":"True or False: William Wordsworth believed poetry should use elevated, archaic language to express emotion.","answer":"False","solution":"Wordsworth advocated for the language of 'real men' and common speech in poetry, rejecting artificial diction."},{"type":"word","q":"What literary term describes the Romantic emphasis on emotion, nature, and the individual imagination?","answer":"Romanticism","solution":"Romanticism prioritizes feeling and imagination over reason, a defining characteristic of the era."}]},{"title":"Victorian Novel & Social Realism","questions":[{"type":"regular","q":"In Charles Dickens' 'Great Expectations,' what is the name of Pip's mysterious benefactor?","answer":"Abel Magwitch","solution":"Magwitch's identity as Pip's patron subverts Pip's assumptions about class and social advancement."},{"type":"regular","q":"Which Victorian novelist is known for depicting the lives of working-class women and industrial society in 'North and South'?","answer":"Elizabeth Gaskell","solution":"Gaskell's novel explores industrial conflict and gender roles in Victorian England through social realism."},{"type":"word","q":"What term describes a novel that realistically portrays social conditions and everyday life, common in Victorian literature?","answer":"Social realism or realism","solution":"Victorian novelists used realism to critique social injustice and document contemporary life authentically."}]},{"title":"Modernist Innovation & Fragmentation","questions":[{"type":"regular","q":"What experimental narrative technique does James Joyce use in 'Ulysses' to represent the stream of consciousness?","answer":"Interior monologue or stream of consciousness","solution":"Joyce's technique mimics the unfiltered flow of characters' thoughts, breaking traditional narrative structure."},{"type":"regular","q":"True or False: T.S. Eliot's 'The Waste Land' presents a coherent, linear narrative of a single protagonist's journey.","answer":"False","solution":"'The Waste Land' is fragmented, allusive, and multi-voiced, reflecting modernist rejection of linear storytelling."},{"type":"word","q":"What literary movement, emerging in early 20th-century Britain, rejected traditional forms and emphasized experimentation?","answer":"Modernism","solution":"Modernism embraced fragmentation, allusion, and formal innovation to reflect the complexities of modern life."}]}]},{"title":"Rhetoric & Persuasive Techniques","subtitle":"Master rhetorical devices and persuasive strategies in speeches and essays.","sections":[{"title":"Classical Rhetoric & Appeals","questions":[{"type":"regular","q":"Which rhetorical appeal relies on the credibility and trustworthiness of the speaker?","answer":"Ethos","solution":"Ethos establishes the speaker's authority and character to persuade the audience."},{"type":"regular","q":"In Martin Luther King Jr.'s 'I Have a Dream' speech, which appeal does he primarily use when describing his vision of equality?","answer":"Pathos","solution":"King uses emotional language and vivid imagery to stir the audience's feelings about justice and equality."},{"type":"word","q":"What is the term for a logical argument that uses evidence and reasoning to persuade?","answer":"Logos","solution":"Logos appeals to reason and logic, using facts, statistics, and sound reasoning to convince an audience."}]},{"title":"Figurative Language & Devices","questions":[{"type":"regular","q":"What rhetorical device is used in the phrase 'I have a thousand things to do today'?","answer":"Hyperbole","solution":"Hyperbole exaggerates for emphasis or effect, making the speaker's point more memorable and persuasive."},{"type":"regular","q":"True or False: Alliteration is the repetition of similar vowel sounds within words in close proximity.","answer":"False","solution":"Alliteration repeats initial consonant sounds; the repetition of vowel sounds is called assonance."},{"type":"word","q":"What device uses a comparison between two unlike things using 'like' or 'as'?","answer":"Simile","solution":"Similes create vivid comparisons that help audiences understand complex ideas through familiar imagery."}]},{"title":"Argument Structure & Fallacies","questions":[{"type":"regular","q":"What logical fallacy occurs when someone attacks the person making an argument rather than the argument itself?","answer":"Ad hominem","solution":"Ad hominem attacks undermine persuasion by focusing on character rather than evidence or reasoning."},{"type":"regular","q":"True or False: A straw man fallacy involves oversimplifying or misrepresenting an opponent's position to make it easier to refute.","answer":"True","solution":"Straw man fallacies distort arguments, making them weaker and easier to attack unfairly."},{"type":"word","q":"What is the term for the main claim or position that a speaker or writer supports with evidence?","answer":"Thesis or claim","solution":"The thesis is the central argument that all supporting evidence and reasoning must reinforce."}]}]},{"title":"Poetry: Form, Meter & Interpretation","subtitle":"Analyze poetic forms, meter, and meaning in classic and contemporary poetry.","sections":[{"title":"Poetic Forms & Structure","questions":[{"type":"regular","q":"What is a 14-line poem with a specific rhyme scheme, often used by Shakespeare and Petrarch?","answer":"Sonnet","solution":"Sonnets follow strict structural rules and are a major form for exploring themes of love and mortality."},{"type":"regular","q":"True or False: A villanelle requires the repetition of two specific lines throughout the poem.","answer":"True","solution":"Villanelles use two refrains that alternate and appear together at the end, creating musical repetition."},{"type":"word","q":"What term describes the division of a poem into groups of lines, similar to paragraphs in prose?","answer":"Stanza","solution":"Stanzas organize poems visually and thematically, helping readers process meaning in sections."}]},{"title":"Meter, Rhythm & Sound","questions":[{"type":"regular","q":"What is the term for a metrical unit consisting of one stressed syllable followed by one unstressed syllable?","answer":"Iamb or iambic foot","solution":"Iambic meter is the most common in English poetry, creating a natural speech-like rhythm."},{"type":"regular","q":"Which poetic device involves the repetition of consonant sounds at the beginning of nearby words?","answer":"Alliteration","solution":"Alliteration creates musicality and emphasis, drawing attention to key words and phrases."},{"type":"word","q":"What is the term for a line of poetry that ends without punctuation, allowing meaning to flow into the next line?","answer":"Enjambment","solution":"Enjambment creates momentum and can emphasize unexpected connections between ideas."}]},{"title":"Imagery, Symbolism & Interpretation","questions":[{"type":"regular","q":"In Robert Frost's 'The Road Not Taken,' what does the fork in the road symbolize?","answer":"Life choices or decisions","solution":"The road fork represents the choices individuals must make and their consequences in life."},{"type":"regular","q":"True or False: Imagery in poetry refers only to visual descriptions and does not include other sensory details.","answer":"False","solution":"Imagery encompasses all sensory details—sight, sound, touch, taste, and smell—to create vivid experiences."},{"type":"word","q":"What is the underlying or implied meaning of a poem, beyond its literal surface meaning?","answer":"Theme or thematic meaning","solution":"Theme expresses the poem's deeper message or insight about human experience and values."}]}]},{"title":"Dramatic Literature & Performance","subtitle":"Examine dramatic structure, character development, and theatrical interpretation.","sections":[{"title":"Dramatic Structure & Elements","questions":[{"type":"regular","q":"What is the turning point in a play where the protagonist's fortune changes, typically occurring near the end?","answer":"Climax","solution":"The climax is the moment of greatest tension where the central conflict reaches its peak."},{"type":"regular","q":"True or False: Exposition in drama must occur only at the very beginning of a play.","answer":"False","solution":"Exposition can occur throughout a play as new information is revealed to advance the plot."},{"type":"word","q":"What is the term for a character's speech delivered alone on stage, revealing inner thoughts to the audience?","answer":"Soliloquy","solution":"Soliloquies provide insight into a character's motivations and psychological state without other characters hearing."}]},{"title":"Character & Conflict","questions":[{"type":"regular","q":"In Shakespeare's 'Hamlet,' what internal conflict does Hamlet experience regarding his father's murder?","answer":"Hesitation about revenge or doubt about his uncle's guilt","solution":"Hamlet's internal struggle between duty and uncertainty drives the play's psychological complexity."},{"type":"regular","q":"What type of character serves as a foil, highlighting the protagonist's qualities through contrast?","answer":"Foil character","solution":"Foil characters emphasize the protagonist's traits by presenting opposing qualities or values."},{"type":"word","q":"What is the struggle between a character and an outside force, such as society or nature?","answer":"External conflict","solution":"External conflict drives plot action and tests the character's resilience against obstacles."}]},{"title":"Tragedy, Comedy & Interpretation","questions":[{"type":"regular","q":"What is a tragic flaw in a protagonist that leads to their downfall?","answer":"Hamartia","solution":"Hamartia is the character's weakness or error in judgment that causes the tragic ending."},{"type":"regular","q":"True or False: Comedies in drama always end with marriage or the restoration of social order.","answer":"True","solution":"Comedic conventions typically resolve conflicts through marriage, reconciliation, or the reestablishment of harmony."},{"type":"word","q":"What is the term for a moment of sudden realization or recognition, often leading to a reversal in fortune?","answer":"Anagnorisis or recognition","solution":"Anagnorisis often triggers the climax and forces characters to confront truth and consequences."}]}]},{"title":"Nonfiction & Memoir: Truth & Narrative","subtitle":"Analyze nonfiction genres, narrative techniques, and the writer's voice and perspective.","sections":[{"title":"Memoir & Personal Essay","questions":[{"type":"regular","q":"What is the primary difference between a memoir and an autobiography?","answer":"A memoir focuses on specific events and themes, while autobiography covers an entire life chronologically.","solution":"Memoirs are selective and thematic, while autobiographies aim for comprehensive life narratives."},{"type":"regular","q":"True or False: A personal essay must always be written in first person and center on the author's experience.","answer":"True","solution":"Personal essays are inherently first-person narratives that explore the author's reflections and insights."},{"type":"word","q":"What is the distinctive way a writer expresses personality, attitude, and perspective in their writing?","answer":"Voice","solution":"Voice includes tone, diction, and perspective, making each writer's nonfiction uniquely recognizable."}]},{"title":"Narrative Techniques & Credibility","questions":[{"type":"regular","q":"What narrative technique involves reflecting on past events from the perspective of the present?","answer":"Retrospective narration or looking back","solution":"Retrospective narration allows writers to provide context and interpretation that immediate narration cannot."},{"type":"regular","q":"Which of the following best establishes credibility in nonfiction: vivid description, specific details, or emotional appeals?","answer":"Specific details","solution":"Specific, verifiable details convince readers of accuracy and authenticity more than emotion or description alone."},{"type":"word","q":"What is the term for a writer's stated or implied position on a subject, revealed through word choice and emphasis?","answer":"Bias or perspective","solution":"Recognizing a writer's bias helps readers evaluate the reliability and limitations of nonfiction accounts."}]},{"title":"Argument in Nonfiction & Essay","questions":[{"type":"regular","q":"In an argumentative essay, what is the purpose of a counterargument?","answer":"To acknowledge and refute opposing viewpoints, strengthening the main argument.","solution":"Counterarguments demonstrate the writer's understanding of complexity and increase persuasiveness."},{"type":"regular","q":"True or False: An effective nonfiction argument relies solely on emotional appeals rather than evidence.","answer":"False","solution":"Strong nonfiction arguments balance emotional appeals with concrete evidence and logical reasoning."},{"type":"word","q":"What term describes a brief, pithy statement that expresses a general truth or principle?","answer":"Aphorism or maxim","solution":"Aphorisms add authority and memorability to nonfiction writing by distilling wisdom into concise statements."}]}]}]);
  addBooks("eng12", [{"title":"American Literature: 20th & 21st Century","subtitle":"Modernism, Harlem Renaissance, and contemporary American voices","sections":[{"title":"Modernism & the Lost Generation","questions":[{"type":"regular","q":"What historical event prompted the disillusionment reflected in 1920s American literature?","answer":"World War I","solution":"WWI shattered optimism and inspired writers like Hemingway and Fitzgerald to explore themes of alienation and moral decay."},{"type":"regular","q":"True or False: F. Scott Fitzgerald's 'The Great Gatsby' is set during the Great Depression.","answer":"False","solution":"The novel is set in the Jazz Age (1922), before the 1929 stock market crash that triggered the Depression."},{"type":"word","q":"What literary technique does Hemingway famously use, characterized by sparse prose and omission of unnecessary details?","answer":"Iceberg theory (or minimalism)","solution":"Hemingway believed in showing only the surface of events, leaving deeper meaning beneath, like an iceberg."}]},{"title":"Harlem Renaissance & African American Voices","questions":[{"type":"regular","q":"Name the decade when the Harlem Renaissance flourished as a cultural and artistic movement.","answer":"1920s (or the twenties)","solution":"The Harlem Renaissance peaked in the 1920s as African American artists, writers, and musicians celebrated Black culture in Harlem, New York."},{"type":"regular","q":"Which Harlem Renaissance poet wrote 'Harlem,' a poem questioning deferred dreams?","answer":"Langston Hughes","solution":"Hughes's 'Harlem' uses vivid imagery to explore what happens when dreams are postponed or denied."},{"type":"word","q":"What is the term for the blending of African American folk traditions with modernist literary techniques?","answer":"Cultural synthesis (or fusion)","solution":"Harlem Renaissance writers merged vernacular speech, blues, and jazz rhythms with formal literary structures."}]},{"title":"Contemporary & Postmodern American Literature","questions":[{"type":"regular","q":"True or False: Postmodern literature typically embraces a single, unified narrative perspective.","answer":"False","solution":"Postmodern works often fragment narrative, use multiple perspectives, and challenge traditional storytelling conventions."},{"type":"regular","q":"Name a contemporary American author known for magical realism or genre-blending fiction (e.g., Colson Whitehead, N.K. Jemisin).","answer":"Colson Whitehead, N.K. Jemisin, or similar contemporary author","solution":"Contemporary American literature increasingly blends genres and incorporates speculative elements to explore identity and history."},{"type":"word","q":"What narrative technique involves the narrator directly addressing or acknowledging the reader?","answer":"Metafiction (or breaking the fourth wall)","solution":"Metafiction self-consciously references its own construction, a hallmark of postmodern American fiction."}]}]},{"title":"Rhetoric & Persuasive Discourse","subtitle":"Ethos, pathos, logos, and strategies of argument in speeches and essays","sections":[{"title":"Classical Rhetorical Appeals","questions":[{"type":"regular","q":"Which rhetorical appeal relies on the credibility and character of the speaker?","answer":"Ethos","solution":"Ethos establishes trust by demonstrating the speaker's expertise, integrity, and authority on the subject."},{"type":"regular","q":"True or False: Pathos is an appeal to the audience's logic and reason.","answer":"False","solution":"Pathos appeals to emotion and values; logos appeals to logic and reason."},{"type":"word","q":"What is the term for the arrangement and structure of arguments in a persuasive text?","answer":"Disposition (or organization)","solution":"Disposition refers to how a speaker orders claims, evidence, and counterarguments for maximum persuasive effect."}]},{"title":"Argument Structure & Fallacies","questions":[{"type":"regular","q":"What is a logical fallacy in which a speaker attacks the opponent rather than the argument?","answer":"Ad hominem","solution":"Ad hominem attacks the person making the argument instead of addressing the substance of their claim."},{"type":"regular","q":"Identify the fallacy: 'Everyone believes this, so it must be true.'","answer":"Appeal to popularity (or bandwagon)","solution":"This fallacy assumes something is true simply because many people believe it, not because of evidence."},{"type":"word","q":"What term describes a statement that is accepted as true without proof or evidence?","answer":"Assumption (or premise)","solution":"An assumption is an unstated belief underlying an argument; strong arguments make assumptions explicit and defensible."}]},{"title":"Analyzing Persuasive Texts & Speeches","questions":[{"type":"regular","q":"In Martin Luther King Jr.'s 'I Have a Dream' speech, what rhetorical device is created by the repeated phrase 'I have a dream'?","answer":"Anaphora","solution":"Anaphora is the repetition of words at the beginning of successive clauses, creating rhythm and emphasis."},{"type":"regular","q":"True or False: A strong persuasive argument must acknowledge and refute counterarguments.","answer":"True","solution":"Addressing counterarguments (refutation) strengthens credibility and demonstrates thorough understanding of the issue."},{"type":"word","q":"What is the term for a brief, memorable statement that encapsulates the main argument of a speech?","answer":"Thesis (or central claim)","solution":"A clear thesis statement guides the entire argument and helps the audience understand the speaker's main position."}]}]},{"title":"Narrative Structure & Literary Form","subtitle":"Plot, characterization, point of view, and narrative techniques in fiction","sections":[{"title":"Plot Architecture & Story Elements","questions":[{"type":"regular","q":"What is the term for the moment of greatest tension or turning point in a narrative?","answer":"Climax","solution":"The climax is the peak of action where the central conflict reaches its most intense point."},{"type":"regular","q":"True or False: Exposition must always occur at the beginning of a story.","answer":"False","solution":"While exposition often opens a narrative, it can be woven throughout the story through dialogue, flashbacks, or other techniques."},{"type":"word","q":"What narrative structure begins in the middle of the action?","answer":"In medias res","solution":"In medias res (Latin for 'in the middle of things') opens a story at an advanced point in the action."}]},{"title":"Character Development & Perspective","questions":[{"type":"regular","q":"What type of narrator has access to the thoughts and feelings of all characters?","answer":"Omniscient narrator","solution":"An omniscient narrator knows everything about all characters and events, providing a god-like perspective."},{"type":"regular","q":"True or False: A round character is one who remains unchanged throughout the narrative.","answer":"False","solution":"A round character is complex and undergoes significant change; a flat character remains static."},{"type":"word","q":"What is the term for a character who opposes the protagonist and drives the central conflict?","answer":"Antagonist","solution":"The antagonist is the opposing force or character that creates obstacles for the protagonist."}]},{"title":"Narrative Techniques & Style","questions":[{"type":"regular","q":"What literary device presents a character's unfiltered thoughts and feelings as they occur?","answer":"Stream of consciousness","solution":"Stream of consciousness mimics the natural flow of a character's mind, often without conventional punctuation or grammar."},{"type":"regular","q":"True or False: Foreshadowing always explicitly tells the reader what will happen next.","answer":"False","solution":"Foreshadowing hints at or suggests future events subtly; explicit revelation would not be foreshadowing."},{"type":"word","q":"What is the term for a narrative that interrupts the main story to tell events from the past?","answer":"Flashback","solution":"A flashback temporarily shifts the narrative to an earlier time to provide context or reveal important information."}]}]},{"title":"Poetry: Forms, Devices, & Interpretation","subtitle":"Meter, rhyme, imagery, and close reading of verse across traditions","sections":[{"title":"Poetic Forms & Meter","questions":[{"type":"regular","q":"What is the term for a 14-line poem with a specific rhyme scheme, often exploring love or mortality?","answer":"Sonnet","solution":"A sonnet is a traditional form with 14 lines; Shakespearean sonnets follow ABAB CDCD EFEF GG rhyme."},{"type":"regular","q":"True or False: Iambic pentameter consists of five stressed syllables per line.","answer":"False","solution":"Iambic pentameter has five iambs (unstressed-stressed pairs) per line, totaling ten syllables with five stresses."},{"type":"word","q":"What is the name of a metrical foot consisting of one unstressed syllable followed by one stressed syllable?","answer":"Iamb (or iambus)","solution":"An iamb is the most common metrical unit in English poetry, creating a natural speaking rhythm."}]},{"title":"Poetic Devices & Imagery","questions":[{"type":"regular","q":"What device compares two unlike things using 'like' or 'as'?","answer":"Simile","solution":"A simile explicitly compares two things using a comparison word; a metaphor compares without 'like' or 'as'."},{"type":"regular","q":"True or False: Alliteration is the repetition of vowel sounds in nearby words.","answer":"False","solution":"Alliteration repeats consonant sounds; assonance repeats vowel sounds."},{"type":"word","q":"What is the term for a word or phrase that appeals to one or more of the five senses?","answer":"Imagery (or sensory image)","solution":"Imagery uses vivid, concrete language to create mental pictures and engage the reader's senses."}]},{"title":"Interpreting Poems & Poetic Voice","questions":[{"type":"regular","q":"What is the term for the speaker or voice in a poem, distinct from the poet?","answer":"Persona (or speaker)","solution":"The persona is the character or voice narrating the poem; it may differ from the poet's actual views."},{"type":"regular","q":"True or False: The theme of a poem is always explicitly stated in the final line.","answer":"False","solution":"Themes are often implied through imagery, tone, and symbolism rather than directly stated."},{"type":"word","q":"What is the term for the emotional quality or atmosphere created by a poem's language and imagery?","answer":"Tone (or mood)","solution":"Tone reflects the speaker's attitude; mood is the emotional atmosphere the poem creates for the reader."}]}]},{"title":"Drama: Plays, Performance, & Theatrical Analysis","subtitle":"Dramatic structure, dialogue, staging, and interpretation of plays from multiple traditions","sections":[{"title":"Dramatic Structure & Conventions","questions":[{"type":"regular","q":"What is the term for a speech in which a character reveals their thoughts directly to the audience?","answer":"Soliloquy","solution":"A soliloquy is an uninterrupted speech where a character speaks aloud alone, revealing inner thoughts to the audience."},{"type":"regular","q":"True or False: A tragedy always ends with the death of the protagonist.","answer":"False","solution":"While many tragedies end in death, the essential element is the protagonist's downfall or spiritual destruction."},{"type":"word","q":"What is the term for a private conversation between two characters on stage, unheard by others?","answer":"Aside","solution":"An aside is a brief remark spoken directly to the audience or to one character, supposedly unheard by others."}]},{"title":"Character & Dialogue in Drama","questions":[{"type":"regular","q":"What dramatic technique uses verbal irony when a character says the opposite of what they mean?","answer":"Sarcasm (or irony)","solution":"Sarcasm is a form of irony that uses mocking or contemptuous language to convey the opposite of literal meaning."},{"type":"regular","q":"True or False: Stage directions are considered dialogue and should be read aloud during a performance.","answer":"False","solution":"Stage directions describe actions, movements, and settings; they guide actors and directors but are not spoken."},{"type":"word","q":"What is the term for a character who represents a single quality or type rather than a complex personality?","answer":"Stock character (or archetype)","solution":"Stock characters are conventional types (the villain, the lover, the fool) used in drama for recognizable roles."}]},{"title":"Staging, Performance, & Interpretation","questions":[{"type":"regular","q":"What is the term for the physical space on stage closest to the audience?","answer":"Downstage","solution":"Downstage is the front of the stage nearest the audience; upstage is the back, farthest from the audience."},{"type":"regular","q":"True or False: A director's interpretation of a play must remain faithful to every detail in the script.","answer":"False","solution":"Directors make creative choices about setting, pacing, and emphasis; multiple valid interpretations of a play exist."},{"type":"word","q":"What is the term for the underlying struggle or tension that propels the dramatic action forward?","answer":"Conflict (or dramatic tension)","solution":"Dramatic conflict—between characters, within a character, or with circumstances—creates the central tension of a play."}]}]}]);
